import re, sys
src = open(sys.argv[1]).read()
start = src.index('xpad_device[] = {') if 'xpad_device[] = {' in src else src.index('} xpad_device[] = {')
end = src.index('};', start)
rows = []
for m in re.finditer(r'\{\s*(0x[0-9a-fA-F]+),\s*(0x[0-9a-fA-F]+),\s*"([^"]*)",\s*([^,]+),\s*(XTYPE_\w+)(?:,\s*([A-Z_]+))?\s*\}', src[start:end]):
    vid, pid, name, mapping, xtype, flags = m.groups()
    if xtype not in ('XTYPE_XBOX360', 'XTYPE_XBOX360W', 'XTYPE_XBOXONE'):
        continue
    if vid == '0x0000':
        continue
    mapping = mapping.strip()
    maps = []
    if mapping != '0':
        for part in mapping.split('|'):
            part = part.strip()
            maps.append('XINPUT_' + part)
    if flags == 'FLAG_DELAY_INIT':
        maps.append('XINPUT_DELAY_INIT')
    name = name.replace('\\', '\\\\')
    rows.append('\t{ %s, %s, %s, %s, "%s" },' % (vid.lower(), pid.lower(),
        xtype.replace('XTYPE_', 'XINPUT_TYPE_'), ' | '.join(maps) or '0', name))
print('''/*
 * Copyright 2026, Renga contributors.
 * Distributed under the terms of the MIT License.
 *
 * Known XInput pads: USB vendor and product, protocol, mapping quirks and
 * the product name the evdev device gets. The list of devices and their
 * quirks is taken from the device table of Linux's xpad driver (facts about
 * the hardware; no code), so a pad gets the same name, and therefore the
 * same SDL mapping database entry, as on Linux. Generated by
 * 3rdparty/ce/tools/gen-xinput-table.py; pads that are not listed still
 * work through their USB interface class, as "Generic X-Box pad".
 */

static const xinput_known_device kXInputDevices[] = {''')
print('\n'.join(rows))
print('};')
